package app.veyra;
import android.app.job.*;import android.content.*;import android.net.Uri;import android.os.Build;import android.provider.DocumentsContract;import org.json.*;import java.io.*;import java.nio.charset.StandardCharsets;import java.util.*;
final class AutoBackup {
 private static boolean opening;
 static synchronized void maybeRun(Context c){if(opening||!due(c,System.currentTimeMillis()))return;opening=true;new Thread(()->{try{write(c,false);}catch(Exception ignored){}finally{synchronized(AutoBackup.class){opening=false;}}},"backup-on-open").start();}
 static final int JOB=7301;static final long DAY=24*60*60*1000L;
 static void schedule(Context c){JobScheduler jobs=c.getSystemService(JobScheduler.class);if(c.getSharedPreferences("auto-backup",0).getString("folder","").isEmpty()){jobs.cancel(JOB);return;}if(jobs.getPendingJob(JOB)!=null)return;JobInfo.Builder b=new JobInfo.Builder(JOB,new ComponentName(c,BackupJob.class)).setPeriodic(DAY,60*60*1000L).setPersisted(true);if(Build.VERSION.SDK_INT>=26)b.setRequiresStorageNotLow(true);jobs.schedule(b.build());}
 static boolean due(Context c,long now){android.content.SharedPreferences p=c.getSharedPreferences("auto-backup",0);return !p.getString("folder","").isEmpty()&&(now-p.getLong("lastSuccess",0)>=DAY||now<p.getLong("lastSuccess",0));}
 static synchronized void write(Context context,boolean force)throws Exception{Context c=context.getApplicationContext();android.content.SharedPreferences p=c.getSharedPreferences("auto-backup",0);String folder=p.getString("folder","");if(folder.isEmpty()||!force&&!due(c,System.currentTimeMillis()))return;byte[] bytes=VelixioData.export(ProfileStore.fixed(c,p.getString("profile","default"))).toString().getBytes(StandardCharsets.UTF_8);if(bytes.length>VelixioData.LIMIT)throw new IOException("Backup too large");Uri tree=Uri.parse(folder),parent=DocumentsContract.buildDocumentUriUsingTree(tree,DocumentsContract.getTreeDocumentId(tree));String name="Velixio-auto-"+new java.text.SimpleDateFormat("yyyyMMdd-HHmmss",Locale.US).format(new Date())+"-"+UUID.randomUUID().toString().substring(0,8)+".velixiodata";Uri created=null;
 try{created=DocumentsContract.createDocument(c.getContentResolver(),parent,"application/octet-stream",name);if(created==null)throw new IOException("Folder unavailable");try(OutputStream out=c.getContentResolver().openOutputStream(created,"wt")){if(out==null)throw new IOException();out.write(bytes);}try(InputStream in=c.getContentResolver().openInputStream(created)){if(in==null)throw new IOException();VelixioData.validate(app.veyra.data.CatalogBackend.read(in,VelixioData.LIMIT));}JSONArray owned=new JSONArray(p.getString("owned","[]"));owned.put(created.toString());JSONArray retained=new JSONArray();for(int i=0;i<owned.length();i++){if(i<owned.length()-7){try{if(!DocumentsContract.deleteDocument(c.getContentResolver(),Uri.parse(owned.getString(i))))retained.put(owned.getString(i));}catch(Exception e){retained.put(owned.getString(i));}}else retained.put(owned.getString(i));}p.edit().putString("owned",retained.toString()).putLong("lastSuccess",System.currentTimeMillis()).remove("error").commit();}
 catch(Exception e){if(created!=null)try{DocumentsContract.deleteDocument(c.getContentResolver(),created);}catch(Exception ignored){}p.edit().putString("error","Backup could not complete. Reconnect the folder or choose another location.").apply();throw e;}}
 static synchronized void configure(Context c,String folder){if(!folder.equals(c.getSharedPreferences("auto-backup",0).getString("folder","")))stop(c);c.getSharedPreferences("auto-backup",0).edit().putString("folder",folder).putString("profile",ProfileStore.id(c)).commit();schedule(c);}
 static synchronized void stop(Context c){android.content.SharedPreferences p=c.getSharedPreferences("auto-backup",0);String folder=p.getString("folder","");p.edit().remove("folder").remove("profile").remove("owned").remove("error").remove("lastSuccess").apply();schedule(c);if(!folder.isEmpty())try{c.getContentResolver().releasePersistableUriPermission(Uri.parse(folder),Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_WRITE_URI_PERMISSION);}catch(Exception ignored){}}
}
